package android.hardware;import java.util.*;public class HardwareBuffer implements AutoCloseable{public static HardwareBuffer last;public static final List<HardwareBuffer> all=new ArrayList<>();public boolean closed;private final int w,h;public HardwareBuffer(){this(1248,1972);}public HardwareBuffer(int w,int h){last=this;this.w=w;this.h=h;all.add(this);}public int getWidth(){return w;}public int getHeight(){return h;}public void close(){closed=true;}}
